{
  "openapi": "3.1.0",
  "info": {
    "title": "Illustrative generated repair API",
    "version": "1"
  },
  "paths": {
    "/tickets": {
      "post": {
        "operationId": "createTicket",
        "responses": {
          "201": {
            "description": "Заявка создана"
          }
        }
      },
      "get": {
        "operationId": "listOwnTickets",
        "responses": {
          "200": {
            "description": "Собственные заявки"
          }
        }
      }
    },
    "/tickets/{id}/status": {
      "patch": {
        "operationId": "changeTicketStatus",
        "parameters": [
          {
            "name": "id",
            "in": "path",
            "required": true,
            "schema": {
              "type": "string",
              "format": "uuid"
            }
          }
        ],
        "responses": {
          "200": {
            "description": "Статус обновлён"
          }
        }
      }
    }
  }
}

{
  "schema_version": "1.0",
  "entities": [
    {
      "id": "ticket",
      "fields": [
        "id",
        "owner_id",
        "description",
        "status"
      ]
    }
  ],
  "note": "Illustrative payload; its detailed schema belongs to A-07."
}

{
  "schema_version": "1.0",
  "ui_kit": "MUI",
  "screens": [
    {
      "id": "tickets",
      "operations": [
        "createTicket",
        "listOwnTickets"
      ]
    }
  ],
  "note": "Illustrative payload; its detailed schema belongs to A-08."
}
